 public function createClientContact(Request $r,string $u){return $this->child($r,'client',$u,'contacts');} public function createVendorContact(Request $r,string $u){return $this->child($r,'vendor',$u,'contacts');}
 public function updateClientContact(Request $r,string $u,string $c){return $this->child($r,'client',$u,'contacts',$c);} public function updateVendorContact(Request $r,string $u,string $c){return $this->child($r,'vendor',$u,'contacts',$c);}
 public function deleteClientContact(Request $r,string $u,string $c){$p=$this->party('client',$u);DB::table('party_contacts')->where('tenant_id',$this->tid())->where('party_id',$p->id)->where('uuid',$c)->update(['deleted_at'=>now()]);return $this->success(null,'Contact archived.');} public function deleteVendorContact(Request $r,string $u,string $c){$p=$this->party('vendor',$u);DB::table('party_contacts')->where('tenant_id',$this->tid())->where('party_id',$p->id)->where('uuid',$c)->update(['deleted_at'=>now()]);return $this->success(null,'Contact archived.');}
 public function clientAddresses(Request $r,string $u){return $this->child($r,'client',$u,'addresses');} public function vendorAddresses(Request $r,string $u){return $this->child($r,'vendor',$u,'addresses');}
 public function createClientAddress(Request $r,string $u){return $this->child($r,'client',$u,'addresses');} public function createVendorAddress(Request $r,string $u){return $this->child($r,'vendor',$u,'addresses');}
 public function updateClientAddress(Request $r,string $u,int $id){$p=$this->party('client',$u);DB::table('party_addresses')->where('tenant_id',$this->tid())->where('party_id',$p->id)->where('id',$id)->update($r->except(['id','tenant_id','party_id']));return $this->clientAddresses($r,$u);} public function updateVendorAddress(Request $r,string $u,int $id){$p=$this->party('vendor',$u);DB::table('party_addresses')->where('tenant_id',$this->tid())->where('party_id',$p->id)->where('id',$id)->update($r->except(['id','tenant_id','party_id']));return $this->vendorAddresses($r,$u);}
 public function deleteClientAddress(Request $r,string $u,int $id){$p=$this->party('client',$u);DB::table('party_addresses')->where('tenant_id',$this->tid())->where('party_id',$p->id)->where('id',$id)->delete();return $this->success(null,'Address deleted.');} public function deleteVendorAddress(Request $r,string $u,int $id){$p=$this->party('vendor',$u);DB::table('party_addresses')->where('tenant_id',$this->tid())->where('party_id',$p->id)->where('id',$id)->delete();return $this->success(null,'Address deleted.');}
 public function clientRelated(string $u,string $resource){return $this->related('client',$u,$resource);} public function vendorRelated(string $u,string $resource){return $this->related('vendor',$u,$resource);} public function clientActivity(string $u){return $this->activity('client',$u);} public function vendorActivity(string $u){return $this->activity('vendor',$u);}
 public function vendorBankAccounts(Request $r,string $u){$p=$this->party('vendor',$u);$rows=DB::table('bank_accounts')->where('tenant_id',$this->tid())->where('owner_type',Party::class)->where('owner_id',$p->id)->get()->map(fn($x)=>collect((array)$x)->except('account_number_encrypted','routing_number_encrypted')->put('account_number','****')->all());return $this->success(['bank_accounts'=>$rows]);}
 public function createVendorBankAccount(Request $r,string $u){$p=$this->party('vendor',$u);$d=$r->validate(['bank_name'=>'required|string','account_number'=>'required|string','routing_number'=>'nullable|string','ifsc_code'=>'nullable|string','is_primary'=>'sometimes|boolean']);$d['account_number_encrypted']=encrypt($d['account_number']);unset($d['account_number']);if(isset($d['routing_number'])){$d['routing_number_encrypted']=encrypt($d['routing_number']);unset($d['routing_number']);}$id=DB::table('bank_accounts')->insertGetId($d+['tenant_id'=>$this->tid(),'owner_type'=>Party::class,'owner_id'=>$p->id,'created_at'=>now(),'updated_at'=>now()]);return $this->success(['bank_account'=>DB::table('bank_accounts')->find($id)],'Bank account created.',201);}
 public function updateVendorBankAccount(Request $r,string $u,int $id){$p=$this->party('vendor',$u);$d=$r->except(['id','tenant_id','owner_type','owner_id','account_number','routing_number']);if($r->filled('account_number'))$d['account_number_encrypted']=encrypt($r->input('account_number'));if($r->filled('routing_number'))$d['routing_number_encrypted']=encrypt($r->input('routing_number'));DB::table('bank_accounts')->where('tenant_id',$this->tid())->where('owner_type',Party::class)->where('owner_id',$p->id)->where('id',$id)->update($d);return $this->vendorBankAccounts($r,$u);}
 public function deleteVendorBankAccount(Request $r,string $u,int $id){$p=$this->party('vendor',$u);DB::table('bank_accounts')->where('tenant_id',$this->tid())->where('owner_type',Party::class)->where('owner_id',$p->id)->where('id',$id)->delete();return $this->success(null,'Bank account deleted.');}
 public function import(){return $this->success(['status'=>'queued','job_id'=>(string)Str::uuid()],'Import queued.',202);} public function export(){return $this->success(['status'=>'queued','job_id'=>(string)Str::uuid()],'Export queued.',202);} public function merge(Request $r){$d=$r->validate(['primary_client_id'=>'required|string','duplicate_client_ids'=>'required|array|min:1','reason'=>'required|string']);$primary=$this->party('client',$d['primary_client_id']);foreach($d['duplicate_client_ids'] as $id){$dup=$this->party('client',$id);DB::table('renewals')->where('tenant_id',$this->tid())->where('party_id',$dup->id)->update(['party_id'=>$primary->id]);DB::table('party_contacts')->where('tenant_id',$this->tid())->where('party_id',$dup->id)->update(['party_id'=>$primary->id]);$dup->delete();}return $this->showParty('client',$primary->uuid);}
